# ! [doc = " Platform-specific extensions to `std` for the WebAssembly System Interface (WASI)."] # ! [doc = ""] # ! [doc = " Provides access to platform-level information on WASI, and exposes"] # ! [doc = " WASI-specific functions that would otherwise be inappropriate as"] # ! [doc = " part of the core `std` library."] # ! [doc = ""] # ! [doc = " It exposes more ways to deal with platform-specific strings (`OsStr`,"] # ! [doc = " `OsString`), allows to set permissions more granularly, extract low-level"] # ! [doc = " file descriptors from files and sockets, and has platform-specific helpers"] # ! [doc = " for spawning processes."] # ! [doc = ""] # ! [doc = " # Examples"] # ! [doc = ""] # ! [doc = " ```no_run"] # ! [doc = " use std::fs::File;"] # ! [doc = " use std::os::wasi::prelude::*;"] # ! [doc = ""] # ! [doc = " fn main() -> std::io::Result<()> {"] # ! [doc = "     let f = File::create(\"foo.txt\")?;"] # ! [doc = "     let fd = f.as_raw_fd();"] # ! [doc = ""] # ! [doc = "     // use fd with native WASI bindings"] # ! [doc = ""] # ! [doc = "     Ok(())"] # ! [doc = " }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " [`OsStr`]: crate::ffi::OsStr"] # ! [doc = " [`OsString`]: crate::ffi::OsString"] # ! [cfg_attr (not (target_env = "p2") , stable (feature = "rust1" , since = "1.0.0"))] # ! [cfg_attr (target_env = "p2" , unstable (feature = "wasip2" , issue = "none"))] # ! [forbid (unsafe_op_in_unsafe_fn)] # ! [doc (cfg (target_os = "wasi"))] use split_decls_genesis :: ourprelude :: * ; pub mod ffi ; pub mod fs ; pub mod io ; #[cfg (all (target_os = "wasi" , target_env = "p1"))] pub mod net ; #[doc = " A prelude for conveniently writing platform-specific code."] #[doc = ""] #[doc = " Includes all extension traits, and some important type definitions."] #[stable (feature = "rust1" , since = "1.0.0")] pub mod prelude { #[doc (no_inline)] #[stable (feature = "rust1" , since = "1.0.0")] pub use super :: ffi :: { OsStrExt , OsStringExt } ; #[doc (no_inline)] #[stable (feature = "rust1" , since = "1.0.0")] pub use super :: fs :: FileTypeExt ; #[doc (no_inline)] #[stable (feature = "rust1" , since = "1.0.0")] pub use super :: fs :: { DirEntryExt , FileExt , MetadataExt , OpenOptionsExt } ; #[doc (no_inline)] #[stable (feature = "rust1" , since = "1.0.0")] pub use super :: io :: { AsFd , AsRawFd , BorrowedFd , FromRawFd , IntoRawFd , OwnedFd , RawFd } ; }